   207→  }
   208→
   209→  if (block.type === "text") {
   210→    return String(block.text || "")
   211→  }
   212→
   213→  if (block.type === "tool_result") {
   214→    const body = toolResultText(block.content)
   215→    return body ? `[tool_result ${block.tool_use_id || ""}]\n${body}`.trim() : ""
   216→  }
   217→
   218→  if (block.type === "tool_use") {
   219→    const input = block.input ? JSON.stringify(block.input) : "{}"
   220→    return `[tool_use ${block.name || ""}] ${input}`.trim()
   221→  }
   222→
   223→  return ""
   224→}
