   336→function summarizeAnthropicMessages(messages = []) {
   337→  const lines = []
   338→
   339→  for (const message of Array.isArray(messages) ? messages : []) {
   340→    const role = String(message?.role || "user").toUpperCase()
   341→    for (const block of normalizeMessageContent(message?.content)) {
   342→      if (block.type === "text") {
   343→        const text = sanitizeClaudeText(block.text || "", 1600)
   344→        if (text) {
   345→          lines.push(`${role}: ${text}`)
   346→        }
   347→        continue
   348→      }
   349→
   350→      if (block.type === "tool_use") {
   351→        lines.push(
   352→          `${role}_TOOL_USE ${String(block.name || "")}: ${compactText(
   353→            JSON.stringify(block.input || {}),
   354→            1000
   355→          )}`
   356→        )
   357→        continue
   358→      }
   359→
   360→      if (block.type === "tool_result") {
   361→        const text = sanitizeClaudeText(toolResultText(block.content), 1600)
   362→        if (text) {
   363→          lines.push(`${role}_TOOL_RESULT ${String(block.tool_use_id || "")}: ${text}`)
   364→        }
   365→      }
   366→    }
   367→  }
   368→
   369→  return lines.slice(-16).join("\n")
   370→}
