   542→function shouldRequireLocalBashTool(userAsk = "", explicitToolName = "") {
   543→  const ask = String(userAsk || "")
   544→  const explicit = String(explicitToolName || "")
   545→  if (explicit === "Bash" || explicit === RUNNER_TOOL.bash) {
   546→    return true
   547→  }
   548→
   549→  const patterns = [
   550→    /\b(run|execute)\b.{0,30}\b(command|bash|shell|script|npm|pnpm|yarn|node|python|git|make|cargo)\b/i,
   551→    /\b(bash|shell|terminal)\b.{0,20}\b(command|script)\b/i,
   552→    /(执行|运行).{0,12}(命令|bash|shell|脚本|终端)/
   553→  ]
   554→  return patterns.some(pattern => pattern.test(ask))
   555→}
