   608→function validatePlannerPolicy(policy = {}) {
   609→  const missingGroups = Array.isArray(policy?.missingGroups) ? policy.missingGroups : []
   610→  if (!missingGroups.length) {
   611→    return
   612→  }
   613→
   614→  const labels = missingGroups.map(group => String(group.label || "required local tool")).join(", ")
   615→  throw new PlannerBoundaryError(
