  1150→function extractResponsesBlocks(payload = {}) {
  1151→  const blocks = []
  1152→
  1153→  for (const item of payload.output || []) {
  1154→    if (!item || typeof item !== "object") continue
  1155→
  1156→    if (item.type === "message") {
  1157→      for (const content of item.content || []) {
  1158→        if (!content || typeof content !== "object") continue
  1159→        if (content.type === "output_text" || content.type === "text") {
  1160→          blocks.push({
  1161→            type: "text",
  1162→            text: String(content.text || "")
  1163→          })
  1164→        }
  1165→      }
  1166→      continue
  1167→    }
  1168→
  1169→    if (item.type === "function_call") {
  1170→      let parsedInput = {}
  1171→      try {
  1172→        parsedInput = item.arguments ? JSON.parse(item.arguments) : {}
  1173→      } catch {
  1174→        parsedInput = {}
  1175→      }
  1176→
  1177→      blocks.push({
  1178→        type: "tool_use",
  1179→        id: String(item.call_id || item.id || `toolu_${randomUUID().replace(/-/g, "")}`),
  1180→        name: String(item.name || ""),
  1181→        input: parsedInput
  1182→      })
  1183→    }
  1184→  }
  1185→
  1186→  return blocks
  1187→}
